/* Summary views consume the shared box score and additive, chronological scoring records. */
function readGameSummaryData(v,bad){
 if(!v||v.version!==1||!Array.isArray(v.events)||v.events.length>3000||!Array.isArray(v.milestones)||v.milestones.length>60||!Number.isInteger(v.periods)||v.periods<1||v.periods>20||typeof v.complete!=='boolean')bad('Invalid game summary');
 let previousIndex=0,previousTime=0;
 const clock=e=>{if(!e||!Number.isInteger(e.index)||e.index<0||e.index>100000||!Number.isInteger(e.seconds)||e.seconds<0||e.seconds>50000||!Number.isInteger(e.period)||e.period<0||e.period>=v.periods||!Number.isInteger(e.playerId)||e.playerId<0||e.playerId>10000000)bad('Invalid summary event');};
 const events=v.events.map(e=>{clock(e);if(![0,1].includes(e.side)||![1,2,3].includes(e.points)||['paint','fast','second','turnover'].some(k=>typeof e[k]!=='boolean')||e.index<previousIndex||e.seconds<previousTime)bad('Invalid scoring event');previousIndex=e.index;previousTime=e.seconds;return Object.fromEntries(['index','seconds','period','side','points','playerId','paint','fast','second','turnover'].map(k=>[k,e[k]]))});
 const milestones=v.milestones.map(e=>{clock(e);if(e.type!=='tripleDouble')bad('Invalid summary milestone');return {index:e.index,seconds:e.seconds,period:e.period,playerId:e.playerId,type:e.type}});
 if(v.teams!==undefined&&(!Array.isArray(v.teams)||v.teams.length!==2||v.teams.some(t=>!t||['abbr','city','name'].some(k=>typeof t[k]!=='string'||t[k].length>200))))bad('Invalid summary teams');
 if(v.featGameId!==undefined&&(typeof v.featGameId!=='string'||v.featGameId.length>250))bad('Invalid feat game ID');
 if(v.featEnvironment!==undefined){const e=v.featEnvironment;if(!e||!['male','female'].includes(e.gender)||!Number.isInteger(e.year)||e.year<1900||e.year>10000||![e.pace,e.scoring].every(x=>Number.isFinite(x)&&x>0&&x<=10))bad('Invalid feat environment');}
 return {...(v.featEnvironment?{featEnvironment:{...v.featEnvironment}}:{}),...(v.featGameId!==undefined?{featGameId:v.featGameId}:{}),...(v.featActions!==undefined?{featActions:readFeatActions(v.featActions,v.periods,bad)}:{}),version:1,events,milestones,periods:v.periods,complete:v.complete,...(v.teams?{teams:v.teams.map(t=>({abbr:t.abbr,city:t.city,name:t.name}))}:{})};
}
function summaryTeams(g){return g.summaryData?.teams||[state.teams[g.a],state.teams[g.b]]}
function summaryPeriodName(g,p){const n=g.gameRules?.gamePeriods||4;return p<n?(n===2?'H':'Q')+(p+1):'OT'+(p-n+1)}
function summaryClock(g,e){const r=g.gameRules||{gamePeriods:4,periodMinutes:12,overtimeMinutes:5},end=e.period<r.gamePeriods?(e.period+1)*r.periodMinutes*60:r.gamePeriods*r.periodMinutes*60+(e.period-r.gamePeriods+1)*r.overtimeMinutes*60,left=Math.max(0,end-e.seconds);return summaryPeriodName(g,e.period)+' '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0')}
function summarizeGame(g,index=Infinity){
 const final=index===Infinity||index>=(g.playByPlay||[]).length,rows=final?g.box:watchBoxRows(g,index),data=g.summaryData,events=data?data.events.filter(e=>final||e.index<=index):null;
 const score=[0,0],biggest=[0,0],largest=[null,null],periods=[],points={paint:[0,0],fast:[0,0],second:[0,0],turnover:[0,0]},flow=[],changes=[],ties=[],runs=[];let lastLeader=null,currentRun=null;
 for(const e of events||[]){score[e.side]+=e.points;(periods[e.period]??=[0,0])[e.side]+=e.points;const diff=score[0]-score[1],leader=diff>0?0:diff<0?1:null;
  biggest[0]=Math.max(biggest[0],diff);biggest[1]=Math.max(biggest[1],-diff);
  if(leader===null)ties.push(e);else {if(lastLeader!==null&&leader!==lastLeader)changes.push({...e,leader,eventOrder:flow.length});lastLeader=leader;}
  if(!currentRun||currentRun.side!==e.side){currentRun={side:e.side,points:0,start:e,end:e};runs.push(currentRun)}currentRun.points+=e.points;currentRun.end=e;
  if(!largest[e.side]||currentRun.points>largest[e.side].points)largest[e.side]={...currentRun};
  for(const key of Object.keys(points))if(e[key])points[key][e.side]+=e.points;
  flow.push({...e,diff,score:[...score]});
 }
 const available=!!events&&(!final||data.complete&&score[0]===g.sa&&score[1]===g.sb);
 const visibleClock=final?null:watchClock(g,index),match=visibleClock?.period.match(/^(Q|OT)(\d+)$/),currentPeriod=match?(match[1]==='OT'?(g.gameRules?.gamePeriods||4)+Number(match[2])-1:Number(match[2])-1):0;
 const count=final?(data?.periods||g.gameRules?.gamePeriods||4):Math.max(currentPeriod+1,periods.length,1);
 const totals=rows?summaryTeams(g).map(t=>gameBoxTeamTotals(g,rows,t,final?Infinity:index)):null;
 const bench=rows?summaryTeams(g).map(t=>{const ps=rows.filter(p=>p.team===t.abbr);return ps.length&&ps.every(p=>Number.isFinite(p.gs))?ps.filter(p=>p.gs===0).reduce((n,p)=>n+p.pts,0):null}):[null,null];
 return {final,index,rows,events,available,score:final?[g.sa,g.sb]:events?score:[watchFrame(g,index).a,watchFrame(g,index).b],biggest,largest,periods,count,points,flow,changes,ties,runs,currentRun,totals,bench,currentLeader:score[0]===score[1]?null:score[0]>score[1]?0:1};
}
function summaryLeaders(rows,abbr,key){if(!rows)return [];const eligible=rows.filter(p=>p.team===abbr&&Number.isFinite(p[key])),max=Math.max(0,...eligible.map(p=>p[key]));return max>0?eligible.filter(p=>p[key]===max).sort((a,b)=>a.name.localeCompare(b.name)||(a.playerId||0)-(b.playerId||0)):[]}
function summaryOpenPlayer(id){if(liveWatch){liveWatch.paused=true;clearTimeout(liveWatchTimer)}if(playerContext(id))return openPlayerProfile(id);const person=state.family?.people?.find(p=>p.playerId===id);if(person&&typeof familyOpen==='function')return familyOpen(person.id);toast('This player’s profile is no longer available in this career.')}
function summaryPlayer(row){const p=playerContext(row.playerId)?.p,relative=state.family?.people?.find(n=>n.playerId===row.playerId),portrait=p?.portrait||relative?.portrait;return (portrait&&validTeamLogo(portrait)?'<img class="summary-portrait" alt="" src="'+escapeHTML(portrait)+'">':'')+(Number.isInteger(row.playerId)?'<button class="namebutton" onclick="summaryOpenPlayer('+row.playerId+')">'+escapeHTML(row.name)+'</button>':escapeHTML(row.name))}
function summaryChart(g,s){
 if(!s.available)return '<p class="muted">Game-flow events unavailable for this game.</p>';
 const r=g.gameRules||{gamePeriods:4,periodMinutes:12,overtimeMinutes:5},reg=r.gamePeriods*r.periodMinutes*60,current=s.flow.at(-1)?.seconds||0,duration=s.final?reg+Math.max(0,s.count-r.gamePeriods)*r.overtimeMinutes*60:Math.max(reg,current),max=Math.max(5,...s.flow.map(e=>Math.abs(e.diff))),x=t=>45+t/duration*600,y=d=>110-d/max*75,points=[[45,110],...s.flow.map(e=>[x(e.seconds),y(e.diff)])];
 const lines=Array.from({length:s.count},(_,p)=>{const t=p<r.gamePeriods?p*r.periodMinutes*60:reg+(p-r.gamePeriods)*r.overtimeMinutes*60;return '<line x1="'+x(t)+'" y1="28" x2="'+x(t)+'" y2="190" class="summary-boundary"/><text x="'+(x(t)+4)+'" y="212">'+summaryPeriodName(g,p)+'</text>'}).join('');
 return '<div class="summary-chart-scroll"><svg class="summary-chart" viewBox="0 0 680 230" role="img" aria-label="Score differential over time. Positive: home lead; negative: away lead."><text x="2" y="38">+'+max+'</text><text x="20" y="114">0</text><text x="2" y="189">−'+max+'</text>'+lines+'<line x1="45" y1="110" x2="645" y2="110" class="summary-zero"/><polyline points="'+points.map(p=>p.join(',')).join(' ')+'" fill="none" class="summary-flow"/>'+s.flow.map(e=>'<circle cx="'+x(e.seconds)+'" cy="'+y(e.diff)+'" r="2"><title>'+summaryClock(g,e)+' · '+e.score.join('–')+' · '+(e.diff>=0?'+':'')+e.diff+'</title></circle>').join('')+'</svg></div><p class="muted">Positive = home lead · Negative = away lead. Hover over a point or expand the scoring events below.</p><details><summary>Inspect scoring events</summary><ol class="summary-event-list">'+s.flow.map(e=>'<li>'+summaryClock(g,e)+' · '+escapeHTML(summaryTeams(g)[e.side].abbr)+' +'+e.points+' · '+e.score.join('–')+'</li>').join('')+'</ol></details>';
}
function summaryHighlights(g,s){
 if(!s.available)return [];
 const highlights=[],names=new Map((s.rows||[]).map(p=>[p.playerId,p.name])),byPeriod=new Map();
 for(const e of s.events){const key=e.playerId+':'+e.period,old=byPeriod.get(key)||0,next=old+e.points;byPeriod.set(key,next);if(old<15&&next>=15)highlights.push({e,text:(names.get(e.playerId)||'Player')+' reached '+next+' points in '+summaryPeriodName(g,e.period)+'.'})}
 for(const run of s.runs.filter(r=>r.points>=8))highlights.push({e:run.end,text:summaryTeams(g)[run.side].city+' put together a '+run.points+'–0 unanswered run ('+summaryClock(g,run.start)+' to '+summaryClock(g,run.end)+').'});
 for(const m of g.summaryData.milestones)if(s.final||m.index<=s.index)highlights.push({e:m,text:(names.get(m.playerId)||'Player')+' recorded a triple-double.'});
 if(s.final){const winner=g.sa>g.sb?0:1,deficit=s.biggest[1-winner],last=s.events.at(-1);if(deficit>=20&&last)highlights.push({e:last,text:summaryTeams(g)[winner].city+' won after trailing by '+deficit+' points.'});

 }
 const lastReg=(g.gameRules?.gamePeriods||4)-1,fourth=s.changes.filter(e=>e.period===lastReg);if(fourth.length>=3)highlights.push({e:fourth.at(-1),text:summaryPeriodName(g,lastReg)+' featured '+fourth.length+' lead changes.'});
 return highlights.sort((a,b)=>a.e.seconds-b.e.seconds||a.e.index-b.e.index);
}
function gameSummaryMarkup(g,index=Infinity){
 const s=summarizeGame(g,index),teams=summaryTeams(g),num=n=>Number.isFinite(n)?n:'—',teamName=side=>escapeHTML(teams[side].city+' '+teams[side].name),table=(headers,rows)=>'<div class="summary-table-scroll"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((v,i)=>i?'<td>'+v+'</td>':'<th scope="row">'+v+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const leaders=table(['Leader',...teams.map(t=>escapeHTML(t.abbr))],[['pts','Points'],['reb','Rebounds'],['ast','Assists'],['stl','Steals'],['blk','Blocks'],['tpm','3-pointers made']].map(([k,label])=>[label,...teams.map(t=>{const ps=summaryLeaders(s.rows,t.abbr,k);return ps.length?ps.map(p=>'<div class="summary-player">'+summaryPlayer(p)+' <strong>'+p[k]+'</strong></div>').join(''):'—'})]));
 const comparison=table(['Statistic',...teams.map(t=>escapeHTML(t.abbr))],[['Biggest lead',...s.biggest.map(v=>s.available?v:'—')],['Points in paint',...s.points.paint.map(v=>s.available?v:'—')],['Fast-break points',...s.points.fast.map(v=>s.available?v:'—')],['Second-chance points',...s.points.second.map(v=>s.available?v:'—')],['Bench points',...s.bench.map(num)],['Points off turnovers',...s.points.turnover.map(v=>s.available?v:'—')]]);
 const shooting=table(['Statistic',...teams.map(t=>escapeHTML(t.abbr))],[...[["fgm","fga","Field goals"],["tpm","tpa","3-pointers"],["ftm","fta","Free throws"]].flatMap(([m,a,label])=>[[label,...teams.map((t,i)=>s.totals?num(s.totals[i][m])+'–'+num(s.totals[i][a]):'—')],[label+' %',...teams.map((t,i)=>s.totals?gameBoxShootingPercent(s.totals[i][m],s.totals[i][a]):'—')]]),...[['reb','Total rebounds'],['orb','Offensive rebounds'],['ast','Assists'],['tov','Turnovers'],['pf','Personal fouls']].map(([k,label])=>[label,...teams.map((t,i)=>s.totals?num(s.totals[i][k]):'—')])]);
 const quarter=s.available?table(['Team',...Array.from({length:s.count},(_,p)=>summaryPeriodName(g,p)),s.final?'Final':'Total'],teams.map((t,i)=>[escapeHTML(t.abbr),...Array.from({length:s.count},(_,p)=>s.periods[p]?.[i]||0),s.score[i]])):'<p class="muted">Period-by-period scoring was not recorded for this game.</p>';
 const last=s.changes.at(-1),lead=s.score[0]===s.score[1]?'Tied':teamName(s.score[0]>s.score[1]?0:1),runText=r=>r?teamName(r.side)+' · '+r.points+'–0 · '+summaryClock(g,r.start)+' → '+summaryClock(g,r.end):'None';
 const highlights=summaryHighlights(g,s),winner=s.score[0]>s.score[1]?0:1;
 const recap=s.final?'<section><h3>Final recap</h3><p>'+teamName(winner)+' defeated '+teamName(1-winner)+' '+s.score[winner]+'–'+s.score[1-winner]+(s.available?', with '+s.changes.length+' lead changes and '+s.ties.length+' ties.':'.')+' '+teams.map(t=>{const ps=summaryLeaders(s.rows,t.abbr,'pts');return ps.length?escapeHTML(t.abbr)+': '+ps.map(p=>escapeHTML(p.name)).join(' / ')+' led with '+ps[0].pts+' points.':''}).join(' ')+(s.available&&s.biggest[1-winner]>=10?' The winner recovered from a '+s.biggest[1-winner]+'-point deficit.':s.available&&s.biggest[winner]>=20?' The winner led by as many as '+s.biggest[winner]+'.':'')+'</p></section>':'';
 return '<div class="game-summary"><h2>'+(s.final?'Game Summary':'Game Summary · Live')+'</h2>'+(!s.available?'<p class="muted">Detailed scoring events are unavailable or incomplete. Only recorded box-score statistics are shown.</p>':'')+recap+'<section><h3>Game leaders</h3><p class="muted">'+(s.final?'Final totals':'Through the current play')+' · Tied leaders are all listed.</p>'+leaders+'</section><section><h3>Game information</h3><div class="summary-facts"><p>Lead changes <strong>'+(s.available?s.changes.length:'—')+'</strong></p><p>Times tied <strong>'+(s.available?s.ties.length:'—')+'</strong></p><p>'+(s.final?'Final leader':'Currently leading')+' <strong>'+lead+'</strong></p><p>Last lead change <strong>'+(s.available?(last?teamName(last.leader)+' · '+summaryClock(g,last):'None'):'—')+'</strong></p></div>'+comparison+'</section><section><h3>Scoring by period</h3>'+quarter+'</section><section><h3>Unanswered scoring runs</h3><p>Current / last run: '+(s.available?runText(s.currentRun):'—')+'</p>'+teams.map((t,i)=>'<p>'+escapeHTML(t.abbr)+' largest: '+(s.available?runText(s.largest[i]):'—')+'</p>').join('')+'</section><section><h3>Game flow</h3>'+summaryChart(g,s)+'</section><section><h3>Team comparison</h3>'+shooting+'</section><section><h3>Game highlights</h3>'+(highlights.length?'<ol class="summary-event-list">'+highlights.map(h=>'<li><strong>'+(h.feat?featClock(g,h.e):summaryClock(g,h.e))+'</strong> · '+(h.feat?featHighlightMarkup(h.feat):escapeHTML(h.text))+'</li>').join(''):'<p class="muted">No supported milestones to show'+(s.final?'.':' yet.')+'</p>')+'</section></div>';
}
